  const titles = {dashboard:['Dashboard','Coordinate student activities, manage events, support student engagement and strengthen campus communication.'],members:['Council Members','Manage council representatives, positions, committees and term information.'],activities:['Activities','Plan and monitor Student Council activities across campus.'],initiatives:['Initiatives','Track student-led initiatives, participation and progress.'],programs:['Student Programs','Coordinate academic, cultural, sports, social and entrepreneurship programs.'],events:['Events','Plan, coordinate and monitor Student Council events and student participation.'],'event-calendar':['Event Calendar','View scheduled council events across the month.'],registrations:['Registrations','Monitor student registrations for council events.'],'event-participants':['Event Participants','Review event participants and registration attendance status.'],announcements:['Announcements','Prepare and manage Student Council communication.'],notices:['Notices','Publish and monitor council notices for students and members.'],notifications:['Notifications','Review council workspace notifications and read status.'],feedback:['Student Feedback','Review student feedback and engagement signals.'],suggestions:['Suggestions','Review, triage and update student suggestions.'],complaints:['Complaints','Monitor student complaints within the council communication boundary.'],reports:['Reports','Review frontend/demo council performance reports.'],analytics:['Analytics','Explore participation, engagement, activity and initiative metrics.'],profile:['Profile','View the current Student Council administrator profile.'],settings:['Settings','Manage council notification and interface preferences.'],'council-structure':['Council Structure','Understand the Student Council hierarchy and committee structure.'],roles:['Roles & Responsibilities','Review council positions and their responsibilities.']};
  function badge(v){const s=String(v).toLowerCase().replace(/\s+/g,'-').replace(/\//g,'-'); return `<span class="badge badge-${s}"><span></span>${esc(v)}</span>`;}
  function header(title,desc,action){return `<div class="page-heading"><div><span class="eyebrow">STUDENT COUNCIL · DEMO WORKSPACE</span><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="page-actions">${action||''}</div></div><div class="dashboard-notice council-demo-notice"><span>${icon('info')}</span><div><strong>Demo Mode</strong><p>Student Council data shown here is sample data for frontend development. Real council management, approvals and database operations will be implemented in later backend phases.</p></div><button class="icon-button" type="button" aria-label="Dismiss demo notice" data-dismiss-council>${icon('close')}</button></div>`;}
  function action(label,href,ic='plus',cls='btn btn-primary'){return `<a class="${cls}" href="${href}">${icon(ic)} ${esc(label)}</a>`;}
  function stateCards(){return `<section class="state-grid"><article class="card compact-state"><span class="state-icon">${icon('document')}</span><div><h3>Empty State</h3><p>No-data presentation ready for future API responses.</p></div><button class="text-button" data-toast="No records found in this demo state.">Preview</button></article><article class="card compact-state loading-preview"><span class="state-icon">${icon('activity')}</span><div><h3>Loading State</h3><p>Skeleton-ready asynchronous data state.</p></div><span class="skeleton-mini"><i></i><i></i><i></i></span></article><article class="card compact-state"><span class="state-icon state-error">${icon('error')}</span><div><h3>Error State</h3><p>Retry-ready API failure presentation.</p></div><button class="text-button" data-toast="Retry is reserved for future API integration.">Try again</button></article></section>`;}
  const tableRegistry = {};
  function table(rows,cols,opts={}){
    const id=opts.id||`council-table-${Math.random().toString(36).slice(2,8)}`;
    const pageSize=Number(opts.pageSize)||6;
    const renderRow=opts.renderRow||((r)=>`<tr>${cols.map(c=>`<td>${esc(r[c]??'')}</td>`).join('')}<td></td></tr>`);
    const filters=opts.filters||[], sortKeys=opts.sortKeys||[];
    tableRegistry[id]={data:rows,cols,opts,pageSize,renderRow};
    return `<div class="card council-data-card" data-council-table="${esc(id)}">
      <div class="section-head">
        <div><h2>${esc(opts.title||'Records')}</h2><p>${esc(opts.description||'Demo data · frontend only')}</p></div>
        <div class="table-toolbar"><button class="btn btn-secondary btn-sm" type="button" data-export-table="${esc(id)}">${icon('download')} Export CSV</button></div>
      </div>
      <div class="council-filter-row">
        ${opts.search!==false?`<label class="filter-search"><span>Search</span><input type="search" data-table-search placeholder="Search records…" aria-label="Search ${esc(opts.title||'records')}"></label>`:''}
        ${filters.map(f=>`<label><span>${esc(f.label)}</span><select data-filter="${esc(f.key)}"><option value="">All</option>${f.values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label>`).join('')}
        ${sortKeys.length?`<label><span>Sort by</span><select data-sort><option value="">Default</option>${sortKeys.map(s=>`<option value="${esc(s.key)}">${esc(s.label)}</option>`).join('')}</select></label>`:''}
      </div>
      <div class="table-wrap"><table id="${esc(id)}"><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}<th class="align-right">Action</th></tr></thead><tbody></tbody></table></div>
      <div class="pagination" data-pagination></div>
    </div>`;
  }

  function getTableRows(state, cfg, wrap){
    let out=[...cfg.data];
    const q=(wrap.querySelector('[data-table-search]')?.value||'').toLowerCase().trim();
    if(q) out=out.filter(r=>Object.values(r).join(' ').toLowerCase().includes(q));
    (cfg.opts.filters||[]).forEach(f=>{
      const v=wrap.querySelector(`[data-filter="${CSS.escape(f.key)}"]`)?.value||'';
      if(v) out=out.filter(r=>String(r[f.key]??'')===v);
    });
    const sk=wrap.querySelector('[data-sort]')?.value||'';
    if(sk){
      out.sort((a,b)=>{
        const av=a[sk], bv=b[sk];
        const an=Number(av), bn=Number(bv);
        if(Number.isFinite(an)&&Number.isFinite(bn)) return an-bn;
        return String(av??'').localeCompare(String(bv??''),undefined,{numeric:true,sensitivity:'base'});
      });
    }
    return out;
  }

  function renderCouncilTable(wrap, resetPage=false){
    const id=wrap.dataset.councilTable, cfg=tableRegistry[id];
    if(!cfg) return;
    const state=wrap._councilTableState||(wrap._councilTableState={current:1});
    if(resetPage) state.current=1;
    const out=getTableRows(state,cfg,wrap);
    const pages=Math.max(1,Math.ceil(out.length/cfg.pageSize));
    state.current=Math.max(1,Math.min(state.current,pages));
    const start=(state.current-1)*cfg.pageSize;
    const tbody=wrap.querySelector('tbody');
    if(tbody){
      tbody.innerHTML=out.slice(start,start+cfg.pageSize).map(r=>cfg.renderRow(r)).join('')||
        `<tr><td colspan="${cfg.cols.length+1}"><div class="table-empty"><strong>No records found.</strong><span>Try changing the search or filters.</span></div></td></tr>`;
    }
    const pager=wrap.querySelector('[data-pagination]');
    if(pager){
      const from=out.length?start+1:0, to=Math.min(start+cfg.pageSize,out.length);
      const first=Math.max(1,state.current-2), last=Math.min(pages,state.current+2);
      pager.innerHTML=`<span>Showing ${from}–${to} of ${out.length}</span><div>
        <button class="table-action" type="button" data-page="prev" ${state.current===1?'disabled':''}>Previous</button>
        ${Array.from({length:last-first+1},(_,i)=>{const n=first+i;return `<button class="table-action ${n===state.current?'active':''}" type="button" data-page="${n}">${n}</button>`;}).join('')}
        <button class="table-action" type="button" data-page="next" ${state.current===pages?'disabled':''}>Next</button>
      </div>`;
    }
  }

  function bindTables(){
    document.querySelectorAll('[data-council-table]').forEach(wrap=>{
      if(wrap.dataset.tableBound==='1'){
        renderCouncilTable(wrap);
        return;
      }
      wrap.dataset.tableBound='1';
      wrap.addEventListener('input',e=>{
        if(e.target.matches('[data-table-search]')) renderCouncilTable(wrap,true);
      });
      wrap.addEventListener('change',e=>{
        if(e.target.matches('[data-filter], [data-sort]')) renderCouncilTable(wrap,true);
      });
      wrap.addEventListener('click',e=>{
        const exportBtn=e.target.closest('[data-export-table]');
        if(exportBtn){
          e.preventDefault();
          const cfg=tableRegistry[wrap.dataset.councilTable];
          if(cfg) exportCSV(getTableRows(wrap._councilTableState||{},cfg,wrap),`${wrap.dataset.councilTable}-filtered.csv`);
          return;
        }
        const memberPreview=e.target.closest('[data-member-preview]');
        if(memberPreview){
          if(memberPreview.dataset.directActionBound==='1') return;
          const r=councilMembers.find(x=>x.id===memberPreview.dataset.memberPreview);
          if(r) richModal('Member Preview',`<div class="council-modal-profile"><span class="avatar avatar-lg">${r.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><div><h3>${r.name}</h3><p>${r.position} · ${r.department}</p></div>${badge(r.status)}</div><div class="council-modal-grid">${[['Member ID',r.id],['Program',r.program],['Semester',r.semester],['Email',r.email],['Phone',r.phone],['Committee',r.committee],['Term',r.termStart+' to '+r.termEnd]].map(x=>`<div class="council-detail"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div>`,[{label:'Close',cls:'btn btn-secondary'}]);
          return;
        }
        const memberEdit=e.target.closest('[data-member-edit]');
        if(memberEdit){
          if(memberEdit.dataset.directActionBound==='1') return;
          const r=councilMembers.find(x=>x.id===memberEdit.dataset.memberEdit);
          if(r) formModal('Edit Council Member',[{name:'name',label:'Name',required:true,value:r.name},{name:'email',label:'Email',type:'email',required:true,value:r.email},{name:'phone',label:'Phone',required:true,value:r.phone},{name:'position',label:'Position',required:true,value:r.position},{name:'committee',label:'Committee',required:true,value:r.committee}],()=>{toast('Council member updated in demo mode only. No data was persisted.','success');return true;});
          return;
        }
        const suggestionAction=e.target.closest('[data-suggestion-status]');
        if(suggestionAction){
          if(suggestionAction.dataset.directActionBound==='1') return;
          const r=suggestions.find(x=>x.id===suggestionAction.dataset.suggestionStatus);
          if(r){const order=['New','Under Review','Accepted','Rejected','Implemented'];r.status=order[(order.indexOf(r.status)+1)%order.length];const cell=suggestionAction.closest('tr')?.querySelector('td:nth-last-child(2)');if(cell)cell.innerHTML=badge(r.status);toast(`Suggestion status changed to ${r.status} in demo mode only.`,'success');}
          return;
        }
        const rowAction=e.target.closest('[data-council-action]');
        if(rowAction){
          const cfg=tableRegistry[wrap.dataset.councilTable];
          if(cfg) preview(rowAction.dataset.councilAction,null,cfg.data);
          return;
        }
        const pageBtn=e.target.closest('[data-page]');
        if(pageBtn && !pageBtn.disabled){
          const state=wrap._councilTableState||(wrap._councilTableState={current:1});
          const cfg=tableRegistry[wrap.dataset.councilTable];
          if(!cfg) return;
          const pages=Math.max(1,Math.ceil(getTableRows(state,cfg,wrap).length/cfg.pageSize));
          const pg=pageBtn.dataset.page;
          if(pg==='prev') state.current--;
          else if(pg==='next') state.current++;
          else state.current=Number(pg);
          state.current=Math.max(1,Math.min(state.current,pages));
          renderCouncilTable(wrap);
        }
      });
      renderCouncilTable(wrap,true);
    });
  }

  function preview(index,id,data){const r=data[Number(index)];if(!r)return; const body=Object.entries(r).map(([k,v])=>`<div class="council-detail"><span>${esc(k.replace(/([A-Z])/g,' $1'))}</span><strong>${esc(v)}</strong></div>`).join(''); richModal('Record Preview',`<div class="council-modal-grid">${body}</div>`,[{label:'Close',cls:'btn btn-secondary'}]);}
  function richModal(title,body,buttons=[]){const root=document.querySelector('#dashboard-modal-root');if(!root)return;root.innerHTML=`<div class="modal-backdrop" data-council-backdrop><section class="dashboard-modal cr-rich-modal council-rich-modal" role="dialog" aria-modal="true" aria-labelledby="council-modal-title"><button class="icon-button modal-close" type="button" aria-label="Close dialog" data-council-close>${icon('close')}</button><div class="modal-icon">${icon('info')}</div><h2 id="council-modal-title">${esc(title)}</h2><div class="cr-modal-body council-modal-body">${body}</div><div class="modal-actions">${buttons.map(b=>`<button type="button" class="${b.cls||'btn btn-primary'}" data-modal-custom="${esc(b.action||'close')}">${esc(b.label)}</button>`).join('')}</div></section></div>`; const close=()=>{root.innerHTML=''};root.querySelectorAll('[data-council-close],[data-modal-custom="close"]').forEach(b=>b.addEventListener('click',close));root.querySelector('[data-council-backdrop]').addEventListener('click',e=>{if(e.target===e.currentTarget)close();});}
  function formModal(title,fields,onSubmit){const body=`<form class="council-form" id="council-modal-form"><div class="council-form-grid">${fields.map(f=>`<label>${esc(f.label)}${f.required?' *':''}<input name="${esc(f.name)}" type="${f.type||'text'}" ${f.required?'required':''} ${f.min?'min="'+f.min+'"':''} ${f.max?'max="'+f.max+'"':''} ${f.value!==undefined?'value="'+esc(f.value)+'"':''}></label>`).join('')}</div><div class="form-actions"><button type="button" class="btn btn-secondary" data-council-close>Cancel</button><button class="btn btn-primary" type="submit">Save Demo Record</button></div></form>`;richModal(title,body,[]);const root=document.querySelector('#dashboard-modal-root');const close=()=>root.innerHTML='';root.querySelectorAll('[data-council-close]').forEach(b=>b.addEventListener('click',close));root.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);if(onSubmit(Object.fromEntries(fd)))close();});}
  function exportCSV(rows,name){if(!rows.length){toast('Nothing to export in this demo view.','warning');return;}const keys=Object.keys(rows[0]);const csv=[keys.join(','),...rows.map(r=>keys.map(k=>`"${String(r[k]??'').replace(/"/g,'""')}"`).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);toast('CSV export completed for demo data.','success');}
  function dashboard(){const stats=[['Council Members','24','21 active','users'],['Active Members','21','87.5% of council','check'],['Ongoing Activities','8','Across campus','activity'],['Upcoming Events','6','Next: 15 Sep','calendar'],['Event Registrations','342','Current cycle','clipboard'],['Pending Feedback','17','Needs review','feedback'],['Open Complaints','9','Within council boundary','message'],['Active Initiatives','12','Student-led programs','spark']];return header('Dashboard',titles.dashboard[1],`${action('Add Council Member','add-member.html')} ${action('Create Event','events.html','calendar','btn btn-secondary')} ${action('Export Report','reports.html','download','btn btn-secondary')}`)+`<section class="stat-grid council-stat-grid">${stats.map(s=>`<article class="stat-card stat-neutral"><div class="stat-card-top"><span class="stat-icon">${icon(s[3])}</span><span class="stat-kicker">${esc(s[2])}</span></div><div class="stat-value">${s[1]}</div><div class="stat-bottom"><strong>${s[0]}</strong><span>Demo</span></div></article>`).join('')}</section><section class="dashboard-grid dashboard-grid-two"><article class="card"><div class="section-head"><div><h2>Monthly Activity Summary</h2><p>Activities, events and participants.</p></div></div><div class="council-bars">${monthly.map(m=>`<div class="council-bar"><i style="--bar:${Math.max(18,m[1]*6)}%"></i><strong>${m[1]}</strong><span>${m[0]}</span><small>${m[3]} participants</small></div>`).join('')}</div></article><article class="card"><div class="section-head"><div><h2>Quick Actions</h2><p>Common council workspace shortcuts.</p></div></div><div class="quick-action-grid council-actions">${[['Add Council Member','add-member.html','users'],['Create Event','#','calendar'],['Create Announcement','announcements.html','notice'],['Add Initiative','initiatives.html','spark'],['View Feedback','feedback.html','feedback'],['Export Report','#','download']].map(a=>`<a class="quick-action" href="${a[1]}" data-council-quick="${a[0]}"><span>${icon(a[2])}</span><span><strong>${a[0]}</strong><small>Open council workflow</small></span>${icon('chevron')}</a>`).join('')}</div></article></section><section class="dashboard-grid dashboard-grid-two"><article class="card"><div class="section-head"><div><h2>Council Members</h2><p>Current representative overview.</p></div>${action('View Members','members.html','users','text-button')}</div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Name</th><th>Position</th><th>Department</th><th>Status</th></tr></thead><tbody>${councilMembers.slice(0,5).map(m=>`<tr><td>${m.id}</td><td><strong>${m.name}</strong></td><td>${m.position}</td><td>${m.department}</td><td>${badge(m.status)}</td></tr>`).join('')}</tbody></table></div></article><article class="card"><div class="section-head"><div><h2>Upcoming Events</h2><p>Coordinated council activities.</p></div>${action('View Events','events.html','calendar','text-button')}</div><div class="council-list">${events.slice(0,4).map(e=>`<div class="council-list-row"><span class="council-date">${e.date.slice(8)}</span><div><strong>${e.name}</strong><small>${e.category} · ${e.venue} · ${e.participants} registered</small></div>${badge(e.status)}</div>`).join('')}</div></article></section><section class="dashboard-grid dashboard-grid-two"><article class="card"><div class="section-head"><div><h2>Engagement Snapshot</h2><p>Feedback, suggestions and participation.</p></div></div><div class="metric-list"><div><span>Feedback received</span><strong>96</strong><i style="--bar:82%"></i></div><div><span>Suggestions submitted</span><strong>48</strong><i style="--bar:64%"></i></div><div><span>Event registrations</span><strong>342</strong><i style="--bar:91%"></i></div><div><span>Active participants</span><strong>278</strong><i style="--bar:76%"></i></div></div></article><article class="card"><div class="section-head"><div><h2>Attention & Communication</h2><p>Items requiring council review or escalation.</p></div></div><div class="council-list">${[['17 feedback items pending','Review feedback','feedback'],['9 complaints open','Follow communication hierarchy','message'],['3 announcements scheduled','Review publication dates','notice'],['4 initiatives nearing milestones','Check progress updates','spark']].map(a=>`<div class="council-alert-row"><span>${icon(a[2])}</span><div><strong>${a[0]}</strong><small>${a[1]}</small></div></div>`).join('')}</div></article></section>${stateCards()}`;}
  function listPage(key){const configs={members:{data:councilMembers,cols:['id','name','position','department','status'],filters:[{key:'position',label:'Position',values:[...new Set(councilMembers.map(x=>x.position))]},{key:'department',label:'Department',values:[...new Set(councilMembers.map(x=>x.department))]},{key:'status',label:'Status',values:['Active','Inactive']}],sortKeys:[{key:'name',label:'Name'},{key:'position',label:'Position'}],title:'Council Members'},activities:{data:activities,cols:['id','title','category','organizer','date','participants','status'],filters:[{key:'category',label:'Category',values:[...new Set(activities.map(x=>x.category))]},{key:'status',label:'Status',values:['Planned','Ongoing','Completed','Cancelled']}],sortKeys:[{key:'title',label:'Title'},{key:'date',label:'Date'},{key:'participants',label:'Participants'}],title:'Council Activities'},programs:{data:programs,cols:['id','name','category','coordinator','date','participants','budget','status'],filters:[{key:'category',label:'Category',values:[...new Set(programs.map(x=>x.category))]},{key:'status',label:'Status',values:['Planned','Scheduled']}],sortKeys:[{key:'date',label:'Date'},{key:'participants',label:'Participants'}],title:'Student Programs'},registrations:{data:registrations,cols:['id','student','event','date','status'],filters:[{key:'event',label:'Event',values:[...new Set(registrations.map(x=>x.event))]},{key:'status',label:'Status',values:['Confirmed','Pending','Cancelled']}],sortKeys:[{key:'date',label:'Registration Date'},{key:'status',label:'Status'}],title:'Event Registrations'},participants:{data:participants,cols:['id','name','studentId','event','registration','attendance'],filters:[{key:'registration',label:'Registration',values:['Confirmed','Pending','Cancelled']},{key:'attendance',label:'Attendance',values:['Present','Registered','Absent','Not Marked']}],sortKeys:[{key:'name',label:'Name'},{key:'event',label:'Event'}],title:'Event Participants'},announcements:{data:announcements,cols:['id','title','category','date','expiry','audience','status'],filters:[{key:'category',label:'Category',values:[...new Set(announcements.map(x=>x.category))]},{key:'status',label:'Status',values:['Draft','Published','Scheduled','Expired']}],sortKeys:[{key:'date',label:'Published Date'},{key:'title',label:'Title'}],title:'Announcements'},notices:{data:notices,cols:['id','title','category','date','status'],filters:[{key:'category',label:'Category',values:[...new Set(notices.map(x=>x.category))]},{key:'status',label:'Status',values:['Active','Archived']}],sortKeys:[{key:'date',label:'Date'}],title:'Notices'},feedback:{data:feedback,cols:['id','student','category','rating','date','status'],filters:[{key:'category',label:'Category',values:[...new Set(feedback.map(x=>x.category))]},{key:'rating',label:'Rating',values:['5','4','3','2','1']},{key:'status',label:'Status',values:['Reviewed','Pending','Under Review']}],sortKeys:[{key:'rating',label:'Rating'},{key:'date',label:'Date'}],title:'Student Feedback'},suggestions:{data:suggestions,cols:['id','student','category','text','date','status'],filters:[{key:'category',label:'Category',values:[...new Set(suggestions.map(x=>x.category))]},{key:'status',label:'Status',values:['New','Under Review','Accepted','Rejected','Implemented']}],sortKeys:[{key:'date',label:'Date'},{key:'status',label:'Status'}],title:'Student Suggestions'},complaints:{data:complaints,cols:['id','student','category','priority','date','status','assigned'],filters:[{key:'priority',label:'Priority',values:['Low','Medium','High','Critical']},{key:'category',label:'Category',values:[...new Set(complaints.map(x=>x.category))]},{key:'status',label:'Status',values:['New','Under Review','Escalated','Resolved','Closed']}],sortKeys:[{key:'priority',label:'Priority'},{key:'date',label:'Date'}],title:'Student Complaints'}};const c=configs[key];let extra='';if(key==='members')extra=action('Add Member','add-member.html','plus');if(key==='events')extra=action('Create Event','#','plus');if(key==='announcements')extra='<button class="btn btn-primary" type="button" data-create-announcement>'+icon('plus')+' Create Announcement</button>';return header(c.title,titles[key][1],extra)+table(c.data,c.cols,{title:c.title,filters:c.filters,sortKeys:c.sortKeys,renderRow:r=>`<tr>${c.cols.map(k=>`<td>${k==='status'||k==='priority'?badge(r[k]):k==='rating'?`<strong>${r[k]} / 5</strong>`:esc(r[k])}</td>`).join('')}<td class="align-right"><button class="table-action" data-council-action="${c.data.indexOf(r)}">Preview</button></td></tr>`})+stateCards();}
  function structure(){const levels=[['President','Aarav Sharma','Executive Council'],['Vice President','Ananya Patil','Executive Council'],['General Secretary','Rohan Deshmukh','Administration'],['Joint Secretary','Kabir More','Administration'],['Cultural Secretary','Sneha Kulkarni','Cultural Committee'],['Sports Secretary','Aditya Joshi','Sports Committee'],['Technical Secretary','Meera Shah','Technical Committee'],['Class Representatives','24 representatives','Class Coordination']];return header('Council Structure',titles['council-structure'][1])+`<section class="card council-hierarchy"><div class="hierarchy-root"><span>${icon('users')}</span><strong>Student Council</strong><small>Institutional student representation</small></div><div class="hierarchy-grid">${levels.map((x,i)=>`<article><span class="hierarchy-index">${String(i+1).padStart(2,'0')}</span><div><h3>${x[0]}</h3><p>${x[1]}</p><small>${x[2]}</small></div></article>`).join('')}</div></section>`+stateCards();}
  function roles(){const rs=[['President','Lead council meetings; coordinate activities; represent students; coordinate with administration.'],['Vice President','Assist the President; coordinate committees; monitor activities.'],['General Secretary','Maintain records; prepare meeting documentation; coordinate communication.'],['Joint Secretary','Support council administration; coordinate schedules and member follow-ups.'],['Cultural Secretary','Coordinate cultural programs, student performers and cultural committees.'],['Sports Secretary','Coordinate sports activities, teams, venues and participation.'],['Technical Secretary','Coordinate technical events, workshops and student technology initiatives.']];return header('Roles & Responsibilities',titles.roles[1])+`<section class="roles-grid">${rs.map(r=>`<article class="card role-card"><span class="role-icon">${icon('users')}</span><h2>${r[0]}</h2><p>${r[1]}</p></article>`).join('')}</section>`+stateCards();}
  function initiativesPage(){return header('Initiatives',titles.initiatives[1],`<button class="btn btn-primary" type="button" data-create-initiative>${icon('plus')} Create Initiative</button>`)+`<section class="initiative-grid">${initiatives.map(x=>`<article class="card initiative-card"><div class="section-head"><div><span class="eyebrow">${x.id}</span><h2>${x.title}</h2></div>${badge(x.status)}</div><p>${x.description}</p><div class="initiative-meta"><span>Coordinator<strong>${x.coordinator}</strong></span><span>Participants<strong>${x.participants}</strong></span><span>Start date<strong>${x.start}</strong></span></div><div class="progress-label"><span>Progress</span><strong>${x.progress}%</strong></div><div class="progress-track"><i style="width:${x.progress}%"></i></div><div class="card-actions"><button class="table-action" data-initiative="${x.id}">View details</button></div></article>`).join('')}</section>`+stateCards();}
  function calendar(){const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];return header('Event Calendar',titles['event-calendar'][1])+`<section class="card"><div class="section-head"><div><h2>September 2026</h2><p>Frontend calendar view · select an event to preview.</p></div><span class="badge badge-upcoming"><span></span>${events.filter(e=>e.status!=='Completed').length} upcoming</span></div><div class="calendar-weekdays">${days.map(d=>`<span>${d}</span>`).join('')}</div><div class="council-calendar">${Array.from({length:30},(_,i)=>{const d=String(i+1).padStart(2,'0');const es=events.filter(e=>e.date==='2026-09-'+d);return `<article class="calendar-day"><strong>${i+1}</strong>${es.map(e=>`<button type="button" data-calendar-event="${e.id}">${e.name}</button>`).join('')}</article>`}).join('')}</div></section><section class="card"><div class="section-head"><div><h2>Upcoming Event List</h2><p>Next scheduled council events.</p></div></div><div class="council-list">${events.filter(e=>e.status!=='Completed').map(e=>`<div class="council-list-row"><span class="council-date">${e.date.slice(8)}</span><div><strong>${e.name}</strong><small>${e.category} · ${e.venue} · ${e.start}–${e.end}</small></div>${badge(e.status)}</div>`).join('')}</div></section>`;}
  function reports(){const reports=[['Event Participation Report','Registrations and participation across council events.','events'],['Activity Report','Council activities by category, organizer and status.','activity'],['Student Engagement Report','Feedback, suggestions and participation indicators.','users'],['Initiative Performance Report','Progress and participant counts for active initiatives.','spark'],['Council Performance Report','Overall council activity and communication metrics.','chart']];return header('Reports',titles.reports[1])+`<section class="reports-grid">${reports.map(r=>`<article class="card report-card"><span>${icon(r[2])}</span><h2>${r[0]}</h2><p>${r[1]}</p><div><button class="btn btn-secondary btn-sm" data-report-preview="${r[0]}">Preview</button><button class="btn btn-primary btn-sm" data-report-export="${r[0]}">${icon('download')} Export CSV</button></div></article>`).join('')}</section><div class="dashboard-notice"><span>${icon('info')}</span><div><strong>Reporting boundary</strong><p>These are frontend/demo reports only. Official institutional reporting will use authorized backend data in a later phase.</p></div></div>`;}
  function analytics(){return header('Analytics',titles.analytics[1])+`<section class="dashboard-grid dashboard-grid-two"><article class="card"><div class="section-head"><div><h2>Event Participation</h2><p>Registered participants by event category.</p></div></div><div class="metric-list">${[['Technical',180],['Cultural',240],['Sports',320],['Social',140]].map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong><i style="--bar:${Math.round(x[1]/3.5)}%"></i></div>`).join('')}</div></article><article class="card"><div class="section-head"><div><h2>Student Engagement</h2><p>Current demo engagement indicators.</p></div></div><div class="council-analytics-stats"><strong>96<small>Feedback received</small></strong><strong>48<small>Suggestions submitted</small></strong><strong>342<small>Event registrations</small></strong><strong>278<small>Active participants</small></strong></div></article></section><section class="card"><div class="section-head"><div><h2>Activity Distribution</h2><p>Activities across council categories.</p></div></div><div class="analytics-bars">${[['Technical',2],['Cultural',2],['Sports',2],['Social',2],['Academic',1]].map(x=>`<div><span>${x[0]}</span><i style="--bar:${x[1]*24}%"></i><strong>${x[1]}</strong></div>`).join('')}</div></section><section class="card"><div class="section-head"><div><h2>Initiative Progress</h2><p>Progress values are derived from the centralized demo dataset.</p></div></div>${initiatives.map(x=>`<div class="progress-row"><span>${x.title}</span><i><b style="width:${x.progress}%"></b></i><strong>${x.progress}%</strong></div>`).join('')}</section>`;}
  function profile(){return header('Profile',titles.profile[1],`<button class="btn btn-primary" type="button" data-edit-profile>${icon('profile')} Edit Profile</button>`)+`<section class="card profile-card"><div class="profile-large"><span class="avatar avatar-xl">SK</span><div><span class="eyebrow">COUNCIL ADMINISTRATOR</span><h2>Sahil Kaware</h2><p>Student Council Administrator · Frontend Demo Profile</p></div>${badge('Active')}</div><div class="council-detail-grid">${[['Member ID','SC-ADMIN-001'],['Council Position','Student Council Administrator'],['Department','Computer Applications'],['Email','council.admin@campus.example'],['Phone','+91 90000 00000'],['Term','2026 Academic Year'],['Profile Status','Active']].map(x=>`<div class="council-detail"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div></section>`;}
  function settings(){return header('Settings',titles.settings[1])+`<section class="card settings-grid"><div><h3>Account Settings</h3><p>Demo preferences are applied to the current browser view only.</p></div><label>Name<input value="Sahil Kaware" aria-label="Name"></label><label>Email<input type="email" value="council.admin@campus.example" aria-label="Email"></label><label>Phone<input value="+91 90000 00000" aria-label="Phone"></label><div class="setting-row"><span><strong>Event notifications</strong><small>Receive event-related workspace notifications.</small></span><input type="checkbox" checked></div><div class="setting-row"><span><strong>Feedback notifications</strong><small>Receive new student feedback alerts.</small></span><input type="checkbox" checked></div><div class="setting-row"><span><strong>Complaint notifications</strong><small>Receive complaint status notifications within permitted scope.</small></span><input type="checkbox" checked></div><div class="setting-row"><span><strong>Announcement notifications</strong><small>Receive council publication updates.</small></span><input type="checkbox" checked></div><div class="setting-row"><span><strong>Compact mode</strong><small>Reduce dashboard spacing.</small></span><input type="checkbox"></div><div class="setting-row"><span><strong>Reduce animation</strong><small>Minimize non-essential motion.</small></span><input type="checkbox"></div><div class="form-actions"><button class="btn btn-primary" data-save-settings>Save Demo Preferences</button></div></section>`;}
